use verus::prelude::*;

// solve(n, k) returns a 2‐element vector [lo, hi] where:
//   • If no items are selected (k==0) or all items are selected (k==n),
//     then lo=0 and hi=0.
//   • Otherwise, lo=1 and hi=min(n−k, 2*k).
//
// We require 0 ≤ k ≤ n, and we ensure the vector is exactly [lo,hi] as above.
#[requires(n >= 0 && k >= 0 && k <= n)]
#[ensures(|res: &Vec<i8>| res.len() == 2
    && if k == 0 || k == n {
         // the “edge” cases
         res[0] == 0 && res[1] == 0
       } else {
         // the “general” cases
         let unselected = n - k;
         let expected_max = unselected.min(2 * k);
         res[0] == 1 && res[1] == expected_max
       }
)]
fn solve(n: i8, k: i8) -> Vec<i8> {
    // If no items are selected or all items are selected,
    // there can be no "good" unselected items.
    if k == 0 || k == n {
        return vec![0, 0];
    }

    // Otherwise, the minimum is 1, and the maximum is the lesser of
    // (unselected items) and (twice the selected items).
    let unselected = n - k;
    let x_max = unselected.min(2 * k);

    // optional sanity check inside the body
    assert!(x_max >= 1 && x_max <= unselected && x_max <= 2 * k);

    vec![1, x_max]
}

