    fn test_solve() {
        // Edge cases: k == 0 or k == n
        assert!(solve(5, 0) == vec![0, 0]);
        assert!(solve(5, 5) == vec![0, 0]);
        assert!(solve(1, 0) == vec![0, 0]);
        assert!(solve(1, 1) == vec![0, 0]);

        // General cases
        assert!(solve(5, 1) == vec![1, 2]); // unselected = 4, 2*k = 2 -> max = 2
        assert!(solve(5, 2) == vec![1, 3]); // unselected = 3, 2*k = 4 -> max = 3
        assert!(solve(5, 3) == vec![1, 2]); // unselected = 2, 2*k = 6 -> max = 2
        assert!(solve(10, 4) == vec![1, (10 - 4).min(2 * 4)]); // max = min(6,8) = 6
    }
